class Codec:
    def serialize(self, root) -> str:
        vals = []
        def preorder(node):
            if node:
                vals.append(str(node.val))
                preorder(node.left)
                preorder(node.right)
        preorder(root)
        return ','.join(vals)

    def deserialize(self, data: str):
        if not data:
            return None
        vals = iter(data.split(','))
        def build(lo, hi):
            val = next(vals, None)
            if val is None:
                return None
            val = int(val)
            if val < lo or val > hi:
                return None
            node = TreeNode(val)
            node.left = build(lo, val)
            node.right = build(val, hi)
            return node
        # Use a list to allow "peeking"
        queue = list(map(int, data.split(',')))
        self.idx = 0
        def build2(lo, hi):
            if self.idx >= len(queue) or queue[self.idx] < lo or queue[self.idx] > hi:
                return None
            val = queue[self.idx]
            self.idx += 1
            node = TreeNode(val)
            node.left = build2(lo, val)
            node.right = build2(val, hi)
            return node
        return build2(float('-inf'), float('inf'))

